"""Writes SOURCES.part.json: vendored PR files (from tools/vendor.out.json) plus local (non-PR) files with sha256 pins."""
import hashlib, json, os, sys
pkg = sys.argv[1]
files = json.load(open(os.path.join(pkg, 'tools', 'vendor.out.json')))
local = [
 ('inputs/derived/k492_registers.json', 'derived', 'P1-P5: per-register climb widths of the ck / jp8 local words of #626, from tools/derive_registers.py applied to the CANONICAL-WORD.json.gz files of the k492b rebuild (r40/base/work/k492b/{ck,jp8}-local; rebuild from research/complex-k492-owner-repair code of #626 is RECORDED, not repeated). Binding: the invoice built from it reproduces the PLAN profile of #626 exactly (P1.gate-profile) and kappa to 18 digits'),
 ('inputs/r39s/rho01.cpp', 'tool', 'E2: 0-1 BFS over F2 bank matrices (R39-S), run by checks/e2_rho.py'),
 ('inputs/r39s/rho_bfs.py', 'tool', 'E2: independent Python Dijkstra at P = 2'),
]
ev = [(os.path.join('evidence', r, f), 'evidence') for r in sorted(os.listdir(os.path.join(pkg, 'evidence'))) for f in sorted(os.listdir(os.path.join(pkg, 'evidence', r)))]
desc = {'E2/rho01_P2.txt': 'output of rho01 2 (also regenerated by verify)', 'E2/rho01_P3.txt': 'output of rho01 3 (also regenerated by verify)',
        'E2/rho_bfs_P2.txt': 'output of rho_bfs.py 2', 'E2/R39-S-NOTES.md': 'R39-S card notes: gate, measurement, scope',
        'P1/B15-NOTES.md': 'B15 card notes: invoice chain and knob table', 'P2/B26-NOTES.md': 'B26 card notes: bit knob table (word-level rows RECORDED)',
        'P3/B66-NOTES.md': 'B66 card notes: rate table and #646 decomposition', 'P4/B54-NOTES.md': 'B54 card notes: s = 7 invoice and economics',
        'P5/B11-NOTES.md': 'B11 card notes: frame-SA outcome, blocking histogram', 'P5/B3R-NOTES.md': 'B3R card notes: SSS hourglass climb mass'}
out = list(files)
for rel, kind, used in [(a, b, c) for a, b, c in local] + [(p, k, desc.get(p[len('evidence/'):], '')) for p, k in ev]:
    data = open(os.path.join(pkg, rel), 'rb').read()
    out.append({'file': rel, 'kind': kind, 'sha256': hashlib.sha256(data).hexdigest(), 'used_for': used})
json.dump({'description': 'PR files are copied unchanged (or gzip-compressed with mtime 0): blob = git blob id of the file at the cited commit (for a .gz copy: of the decompressed content). kind=derived/tool/evidence files are local and pinned by sha256.', 'files': out}, open(os.path.join(pkg, 'SOURCES.part.json'), 'w'), indent=1)
